excerpts.ByteTokenizer:
class ByteTokenizer:
    """不學切詞的可還原起點；每個 UTF-8 byte 對應一個 ID。"""

    vocab_size = 264
    pad_id, bos_id, eos_id, user_id, assistant_id, image_id, audio_id, system_id = range(8)

    def encode(self, text):
        return [b + len(SPECIALS) for b in text.encode("utf-8")]

    def decode(self, ids):
        raw = bytes(i - len(SPECIALS) for i in ids if i >= len(SPECIALS))
        return raw.decode("utf-8", errors="replace")

    def state(self):
        return {"type": "byte", "specials": list(SPECIALS)}

excerpts.render_chat:
def render_chat(messages, tokenizer=None):
    """邊界由角色欄位建立；使用者文字不會被解析為特殊 token。"""
    tok = tokenizer or ByteTokenizer()
    ids, targets = [tok.bos_id], [IGNORE]
    roles = {"user": tok.user_id, "assistant": tok.assistant_id, "system": tok.system_id}
    for message in messages:
        role = message["role"]
        if role not in roles or not isinstance(message["content"], str):
            raise ValueError("role 必須是 user/assistant/system，content 必須是文字")
        content = tok.encode(message["content"]) + [tok.eos_id]
        ids += [roles[role]] + content
        targets += [IGNORE] + (content if role == "assistant" else [IGNORE] * len(content))
    if not any(t != IGNORE for t in targets):
        raise ValueError("這筆對話没有可監督的 assistant 答案")
    return torch.tensor(ids[:-1]), torch.tensor(targets[1:])

excerpts.pad_batch:
def pad_batch(examples, pad_id=0, max_length=None):
    """右側 padding；attention 的有效位置和 loss 的有效位置各自保留。"""
    if not examples:
        raise ValueError("batch 不能是空的")
    length = max(len(x) for x, _ in examples)
    if max_length is not None:
        length = min(length, max_length)
    x = torch.full((len(examples), length), pad_id, dtype=torch.long)
    y = torch.full_like(x, IGNORE)
    valid = torch.zeros_like(x, dtype=torch.bool)
    for row, (inputs, labels) in enumerate(examples):
        n = min(length, len(inputs))
        x[row, :n], y[row, :n], valid[row, :n] = inputs[:n], labels[:n], True
        if not (y[row] != IGNORE).any():
            raise ValueError(f"第 {row} 筆截斷後没有有效答案；增加 max_length 或移除這筆")
    return x, y, valid

excerpts.loss_sum:
def loss_sum(logits, labels):
    """先求和再數有效 token，才能正確合併長短不同的 micro-batch。"""
    count = (labels != IGNORE).sum()
    if count.item() == 0:
        raise ValueError("所有 labels 都被忽略：没有可學習的答案")
    loss = F.cross_entropy(
        logits.reshape(-1, logits.shape[-1]), labels.reshape(-1), ignore_index=IGNORE, reduction="sum"
    )
    return loss, count

excerpts.generate:
def generate(model, ids, max_new_tokens=16, temperature=0.0, eos_id=2, use_cache=False):
    """先提供無 padding 版本；遇到長度上限停止，位置不會悄悄回捲。"""
    was_training = model.training
    model.eval()
    sequence, state = ids.clone(), None
    try:
        for _ in range(max_new_tokens):
            if sequence.shape[1] >= model.config.max_length:
                break
            current = sequence if state is None else sequence[:, -1:]
            result = model(current, cache=state if use_cache else None)
            scores = result["logits"][:, -1]
            if temperature <= 0:
                next_id = scores.argmax(-1, keepdim=True)
            else:
                next_id = torch.multinomial((scores / temperature).softmax(-1), 1)
            sequence = torch.cat((sequence, next_id), 1)
            state = result["cache"] if use_cache else None
            if sequence.shape[0] == 1 and next_id.item() == eos_id:
                break
    finally:
        model.train(was_training)
    return sequence

excerpts.text_examples:
def text_examples(records, mode="text", max_length=128, tokenizer=None):
    tok = tokenizer or ByteTokenizer()
    examples = []
    for record in records:
        if mode == "sft":
            messages = record["messages"] if isinstance(record, dict) else record
            x, y = render_chat(messages, tok)
            if len(x) > max_length:
                raise ValueError(f"SFT record has {len(x)} tokens, exceeding {max_length}; crop explicitly upstream")
            examples.append((x, y))
        elif mode == "text":
            text = record["text"] if isinstance(record, dict) else record
            ids = [tok.bos_id] + tok.encode(text) + [tok.eos_id]
            # Every next-token label appears once; chunk boundaries share only the preceding input token.
            for start in range(0, len(ids) - 1, max_length):
                examples.append(shifted(ids[start : start + max_length + 1]))
        else:
            raise ValueError("mode must be text or sft")
    if not examples:
        raise ValueError("No examples to train or evaluate")
    return examples

excerpts._style_record:
def _style_record(row, style, conditional):
    a, b = row["a"], row["b"]
    question = f"{a}+{b}=?"
    if conditional:
        question = f"style={style}; " + question
    answer = str(a + b)
    if style == "vivid":
        answer += "，像把兩組積木合在一起再數。"
    elif style == "json":
        answer = json.dumps({"answer": a + b})
    return _conversation(question, answer, row["family"], style=style, a=a, b=b)
